import { queryReadings, Reading } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function rangeError(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    assert(error instanceof RangeError, `${message}: wrong error type`);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const source: Reading[] = [
  { id: "b", value: 2, recordedAt: 20, station: "S1" },
  { id: "a", value: 2, recordedAt: 30, station: "S2" },
  { id: "c", value: -1, recordedAt: 10, station: "S3" },
  { id: "d", value: 2, recordedAt: 40, station: "S4" },
];
const snapshot = JSON.stringify(source);
const page = queryReadings(source, { page: 1, pageSize: 2, sortBy: "value", direction: "asc" });
equal(page.items.map(item => item.id), ["c", "b"], "ascending stable sort and first page");
equal({ page: page.page, pageSize: page.pageSize, totalItems: page.totalItems, totalPages: page.totalPages },
  { page: 1, pageSize: 2, totalItems: 4, totalPages: 2 }, "page metadata");
const second = queryReadings(source, { page: 2, pageSize: 2, sortBy: "value", direction: "desc" });
equal(second.items.map(item => item.id), ["d", "c"], "descending stable sort and paging");
const byId = queryReadings(source, { page: 1, pageSize: 100, sortBy: "id", direction: "asc" });
equal(byId.items.map(item => item.id), ["a", "b", "c", "d"], "code-unit string sorting");
assert(JSON.stringify(source) === snapshot, "source was mutated");
assert(page.items[1] !== source[0], "returned item aliases source");
(page.items[1] as { value: number }).value = 999;
assert(source[0].value === 2, "mutating returned item changed source");

const beyond = queryReadings(source, { page: 8, pageSize: 3, sortBy: "recordedAt", direction: "asc" });
equal(beyond.items, [], "page beyond last is empty");
assert(beyond.page === 8 && beyond.totalPages === 2, "beyond-last metadata");
const empty = queryReadings([], { page: 3, pageSize: 1, sortBy: "id", direction: "asc" });
equal(empty, { items: [], page: 3, pageSize: 1, totalItems: 0, totalPages: 0 }, "empty input page");

rangeError(() => queryReadings([], { page: 0, pageSize: 1, sortBy: "id", direction: "asc" }), "page lower bound");
rangeError(() => queryReadings([], { page: 1.2, pageSize: 1, sortBy: "id", direction: "asc" }), "noninteger page");
rangeError(() => queryReadings([], { page: 1, pageSize: 0, sortBy: "id", direction: "asc" }), "page size lower bound");
rangeError(() => queryReadings([], { page: 1, pageSize: 101, sortBy: "id", direction: "asc" }), "page size upper bound");
rangeError(() => queryReadings([{ id: "", value: 1, recordedAt: 1, station: "S" }], { page: 1, pageSize: 1, sortBy: "id", direction: "asc" }), "empty ID");
rangeError(() => queryReadings([{ id: "X", value: Infinity, recordedAt: 1, station: "S" }], { page: 1, pageSize: 1, sortBy: "id", direction: "asc" }), "nonfinite value");
rangeError(() => queryReadings([{ id: "X", value: 1, recordedAt: 1.5, station: "S" }], { page: 1, pageSize: 1, sortBy: "id", direction: "asc" }), "noninteger time");
rangeError(() => queryReadings([{ id: "X", value: 1, recordedAt: 1, station: "" }], { page: 1, pageSize: 1, sortBy: "id", direction: "asc" }), "empty station");

